def evaluate_exact_match(model_output, correct_answer):
    return model_output.strip().lower() == correct_answer.lower()

def llm_grade(client, question, answer, rubric):
    r = client.messages.create(
        model="claude-opus-5-5",   # grader differs from the model under test
        max_tokens=16,
        messages=[{"role": "user", "content":
            f"Rubric: {rubric}\nQuestion: {question}\nAnswer: {answer}\n"
            "Reply with only 'correct' or 'incorrect'."}],
    )
    return r.content[0].text.strip() == "correct"
